with ins as (insert into public.artist_discography (artist_slug,artist_id,title,release_type,release_date,year,label,source_url) select x.s,a.id,x.ti,x.ty,x.d::date,x.y,x.l,x.u from json_to_recordset('[{"s":"rafiki","ti":"The Source","ty":"ep","y":2023,"d":null,"l":"Welt Discos","u":"https://buttondown.com/joedelon/archive/welt-discos-rafiki-the-source-ep"},{"s":"rafiki","ti":"New Shifts","ty":"ep","y":2023,"d":"2023-08-09","l":"Krunk Kulture","u":"https://mixmag.asia/read/premiere-rafiki-new-shifts-ep-walk-the-talk-single-premiere"},{"s":"rafiki","ti":"5 AM Dub","ty":"single","y":2023,"d":null,"l":"Krunk Kulture","u":"https://ra.co/reviews/35687"},{"s":"rafiki","ti":"Anand Mahal","ty":"ep","y":2024,"d":null,"l":"Permanent Vacation","u":"https://mixmag.net/feature/the-mix-019-rafiki-dj-interview-mumbai-house-techno-krunk-kulture"},{"s":"rafiki","ti":"Good Luck (with Squidworks)","ty":"ep","y":2025,"d":"2025-06-13","l":"Krunk Kulture","u":"https://rafikisounds.bandcamp.com/album/good-luck"},{"s":"rafiki","ti":"Funky Acid Party (on Jaljeera, Flavours of the East)","ty":"compilation","y":2021,"d":"2021-11-12","l":"Krunk Kulture","u":"https://krunklive.com/artist/rafiki/"},{"s":"rafiki","ti":"Point of View, Vol. 1 (An Acid Experiment)","ty":"compilation","y":2021,"d":"2021-02-22","l":"Regenerate Music","u":"https://krunklive.com/artist/rafiki/"}]'::json) as x(s text,ti text,ty text,y int,d text,l text,u text) join public.artists a on a.slug=x.s where not exists (select 1 from public.artist_discography d where d.artist_slug=x.s and lower(d.title)=lower(x.ti)) on conflict do nothing returning 1) select count(*) from ins;